from dftracer.python import dftracer, dft_fn as DFTracerFn, ai as dft_ai
from torch.utils.data import Dataset, DataLoader


class Images(Dataset):
    @dft_ai.data.item
    def __getitem__(self, i):
        with open(self.files[i], "rb") as f:
            return f.read()


def _worker_init(worker_id):
    dftracer.initialize_log(logfile=None, data_dir=None, process_id=worker_id)


def make_loader(ds):
    return DataLoader(ds, batch_size=4, num_workers=2, worker_init_fn=_worker_init)

