from dftracer.python import dftracer, dft_fn as DFTracerFn, ai as dft_ai


@dft_ai.pipeline.train
def train(model, loader):
    for batch in loader:
        model.step(batch)


@dft_ai.checkpoint.capture
def save_checkpoint(model, path):
    with open(path, "wb") as f:
        f.write(model.state())
